import {watermarkDocument} from './watermark.js';
// Public Supabase publishable/anon key only. Never use a service-role key here.
// Existing quiz integrations use quiz_set_id, not quiz_id.
const CONFIG_KEY='lexamah:supabase';
let config={url:'https://tvycfhrbdtyxmyeymdgo.supabase.co',key:'sb_publishable_B7s2zzncHW0H-ICBEljE0A_srylPjhR'};
try {config={...config,...JSON.parse(localStorage.getItem(CONFIG_KEY)||'{}')};}catch{}
let session=null;
let refreshFlight=null;let administrator=false;
try {session=JSON.parse(sessionStorage.getItem('lexamah:auth')||'null');}catch{}
async function request(path,{method='GET',body,auth=true,prefer='return=representation'}={}) {
 const owner=auth?session?.user?.id:null;if(auth&&session?.refresh_token)await backend.refreshSession();if(auth&&owner!==session?.user?.id)throw new Error('Account changed. Please retry.');
 if(!backend.configured())throw new Error('The account service is not configured. Contact support.');
 const response=await fetch(`${config.url}${path}`,{method,headers:{apikey:config.key,...(auth&&session?.access_token?{Authorization:`Bearer ${session.access_token}`}:(config.key.startsWith('sb_')?{}:{Authorization:`Bearer ${config.key}`})),'Content-Type':'application/json',Prefer:prefer},body:body?JSON.stringify(body):undefined});
 const data=await response.json().catch(()=>null);
 if(!response.ok)throw new Error(data?.msg||data?.message||data?.error_description||data?.error||'The server could not complete this request.');
 return data;
}
export const backend={
 configured:()=>Boolean(config.url&&config.key), config:()=>({...config}), user:()=>session?.user,
 configure(url,key){if(!administrator)throw new Error('Administrator access is required.');const u=new URL(url);if(u.protocol!=='https:'||!u.hostname.endsWith('.supabase.co'))throw new Error('Enter a valid HTTPS Supabase project URL.');if(!key.trim())throw new Error('Enter your publishable or anon key.');if(key.startsWith('sb_secret_'))throw new Error('Use a publishable key, never a secret key.');if(key.includes('.')){try{const payload=JSON.parse(atob(key.split('.')[1].replace(/-/g,'+').replace(/_/g,'/')));if(payload.role==='service_role')throw new Error('A service-role key must never be used in a browser.');}catch(e){if(e.message.includes('service-role'))throw e;}}if(config.url!==u.origin){session=null;sessionStorage.removeItem('lexamah:auth');}config={url:u.origin,key:key.trim()};localStorage.setItem(CONFIG_KEY,JSON.stringify(config));},
 async signIn(username,password){sessionStorage.removeItem('lexamah:recovery');session=await request('/functions/v1/account-login',{method:'POST',body:{username,password},auth:false});session.expires_at ||= Math.floor(Date.now()/1000)+(session.expires_in||3600);sessionStorage.setItem('lexamah:auth',JSON.stringify(session));return session;},
 async signUp(email,password,profile){const data=await request(`/auth/v1/signup${typeof location!=='undefined'&&location.href?'?redirect_to='+encodeURIComponent(location.href.split('#')[0]):''}`,{method:'POST',body:{email,password,data:{full_name:profile.full_name,username:profile.username,institution:profile.institution,level:profile.level,phone_number:profile.phone_number,lexamah_signup:true}},auth:false});if(data.access_token){session=data;sessionStorage.setItem('lexamah:auth',JSON.stringify(session));}return data;},
 async signOut(){try{if(session){try{await request('/rest/v1/rpc/lexamah_release_admin_session',{method:'POST',body:{}});}catch{}await request('/auth/v1/logout?scope=local',{method:'POST'});}}finally{this.clearSession();}},
 clearSession(){session=null;administrator=false;sessionStorage.removeItem('lexamah:auth');sessionStorage.removeItem('lexamah:recovery');},
 adminReady:()=>administrator,
 async read(table){return await request(`/rest/v1/${table}?select=*`);},
 async saveQuizAttempt(attempt,cloud=false){if(!session?.user)throw new Error('Sign in to save your quiz result to your account.');return request(cloud?'/rest/v1/lexamah_quiz_attempts':'/rest/v1/quiz_attempts',{method:'POST',body:{user_id:session.user.id,quiz_set_id:attempt.quiz_set_id,score:attempt.score,total_questions:attempt.total_questions}});},
 async insert(table,payload){return request(`/rest/v1/${table}`,{method:'POST',body:payload});},
 async remove(table,id){return request(`/rest/v1/${table}?id=eq.${encodeURIComponent(id)}`,{method:'DELETE'});}
};

// LexAmah cloud content lives in separate tables to preserve legacy Lexora data.
const cloudTables={subjects:'lexamah_subjects',lectureNotes:'lexamah_lecture_notes',materials:'lexamah_materials',lectures:'lexamah_lectures',cases:'lexamah_cases',flashcards:'lexamah_flashcards',quizSets:'lexamah_quiz_sets',quizQuestions:'lexamah_quiz_questions'};
const BUCKET='lexamah-files';
const encodePath=path=>path.split('/').map(encodeURIComponent).join('/');
Object.assign(backend,{
 async isAdmin(){if(!backend.user())return false;const id=backend.user().id;const allowed=(await request('/rest/v1/rpc/lexamah_is_admin',{method:'POST',body:{}}))===true;if(backend.user()?.id!==id)return false;administrator=allowed;return allowed;},
 async cloudRead(type){const table=cloudTables[type];if(!table)throw new Error('Unknown content type.');return request(`/rest/v1/${table}?select=*&order=created_at.desc`);},
 async cloudSave(type,item,id){if(!backend.user()||!await backend.isAdmin())throw new Error('An administrator account is required.');const table=cloudTables[type];if(!table)throw new Error('Unknown content type.');const data=await request(`/rest/v1/${table}${id?`?id=eq.${encodeURIComponent(id)}`:''}`,{method:id?'PATCH':'POST',body:item});if(!Array.isArray(data)||data.length!==1)throw new Error('No record was saved. Check the admin policies.');return data[0];},
 async cloudDelete(type,id){if(!backend.user()||!await backend.isAdmin())throw new Error('An administrator account is required.');const table=cloudTables[type];if(!table)throw new Error('Unknown content type.');const data=await request(`/rest/v1/${table}?id=eq.${encodeURIComponent(id)}`,{method:'DELETE'});if(!Array.isArray(data)||data.length!==1)throw new Error('No record was deleted. Refresh the dashboard and check permissions.');return data[0];},
 async upload(file,{audioOnly=false,watermark=false,watermarkLabel='LexAmah',watermarkOptions={},onProgress=()=>{}}={}){if(!backend.user()||!await backend.isAdmin())throw new Error('An administrator account is required.');const owner=backend.user().id;if(watermark){if(audioOnly)throw new Error('Watermarking is for documents only.');file=await watermarkDocument(file,{text:watermarkLabel,...watermarkOptions,onProgress});if(backend.user()?.id!==owner||!await backend.isAdmin())throw new Error('Administrator session changed or expired. Sign in and retry.');}onProgress('Uploading file…');if(!file?.size)throw new Error('Choose a non-empty file.');if(file.size>50*1024*1024)throw new Error('Maximum upload size is 50 MB. Choose a smaller file.');const audioTypes=['audio/mpeg','audio/mp4','audio/aac','audio/wav','audio/x-wav','audio/ogg','audio/webm','audio/flac'];const documentTypes=['application/pdf','application/vnd.openxmlformats-officedocument.wordprocessingml.document','text/plain','image/jpeg','image/png'];const allowed=audioOnly?audioTypes:documentTypes;const mimeByExtension={pdf:documentTypes[0],docx:documentTypes[1],txt:'text/plain',jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',mp3:'audio/mpeg',m4a:'audio/mp4',aac:'audio/aac',wav:'audio/wav',ogg:'audio/ogg',webm:'audio/webm',flac:'audio/flac'};const extension=file.name.split('.').pop().toLowerCase();const fallback=mimeByExtension[extension];const mime=allowed.includes(file.type)?file.type:(!file.type||file.type==='audio/x-m4a'?fallback:null);if(!allowed.includes(mime)||!allowed.includes(fallback))throw new Error(audioOnly?'Upload an audio file: MP3, M4A, AAC, WAV, OGG, WebM audio or FLAC.':'Upload a PDF, DOCX, TXT, JPG or PNG file.');const bucket=audioOnly?'lexamah-audio':BUCKET;const name=file.name.replace(/[^a-zA-Z0-9._-]/g,'-').slice(-100);const path=`${backend.user().id}/${crypto.randomUUID()}-${name}`;const response=await fetch(`${config.url}/storage/v1/object/${bucket}/${encodePath(path)}`,{method:'POST',headers:{apikey:config.key,Authorization:`Bearer ${session.access_token}`,'Content-Type':mime,'x-upsert':'false'},body:file});const data=await response.json().catch(()=>null);if(!response.ok)throw new Error(data?.message||data?.error||'File upload failed.');return {storage_path:path,file_name:file.name,file_size:file.size,storage_bucket:bucket,mime_type:mime};},
 async fileURL(path,bucket=BUCKET){if(!['lexamah-files','lexamah-audio'].includes(bucket))throw new Error('Unknown file bucket.');if(!backend.user())throw new Error('Sign in to open uploaded course files.');const data=await request(`/storage/v1/object/sign/${bucket}/${encodePath(path)}`,{method:'POST',body:{expiresIn:bucket==='lexamah-audio'?7200:300}});const value=data?.signedURL||data?.signedUrl;if(!value)throw new Error('The file could not be opened.');const signedPath=value.startsWith('/object/')?'/storage/v1'+value:value;const url=new URL(signedPath,`${config.url}/storage/v1/`);if(url.origin!==new URL(config.url).origin)throw new Error('Unexpected file URL.');return url.href;},
 async deleteFile(path,bucket=BUCKET){if(!['lexamah-files','lexamah-audio'].includes(bucket))throw new Error('Unknown file bucket.');if(!backend.user()||!await backend.isAdmin())throw new Error('An administrator account is required.');return request(`/storage/v1/object/${bucket}`,{method:'DELETE',body:{prefixes:[path]}});},
 async refreshSession(){if(!session?.refresh_token)return;if(session.expires_at&&session.expires_at*1000>Date.now()+60000)return;if(!refreshFlight)refreshFlight=(async()=>{const previous=session;const updated=await request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:session.refresh_token},auth:false});if(session!==previous)return;session={...updated,profile:previous.profile,expires_at:updated.expires_at||Math.floor(Date.now()/1000)+(updated.expires_in||3600)};sessionStorage.setItem('lexamah:auth',JSON.stringify(session));})().finally(()=>{refreshFlight=null;});await refreshFlight;}
});

Object.assign(backend,{
 async protectedDownload(type,id,code){if(!backend.user())throw new Error('Log in before downloading materials or lecture notes.');return request('/functions/v1/content-download',{method:'POST',body:{type,id,code}});},
 profile(){return session?.profile||session?.user?.user_metadata||{};},
 async saveProfile(profile){if(!backend.user())return;const data=await request(`/rest/v1/lexamah_profiles?user_id=eq.${encodeURIComponent(backend.user().id)}`,{method:'PATCH',body:{full_name:profile.name,phone_number:profile.phone_number||'',institution:profile.institution,level:profile.level}});if(!data?.[0])throw new Error('Profile could not be updated. Run the latest Supabase setup.');session.profile=data[0];sessionStorage.setItem('lexamah:auth',JSON.stringify(session));}
});

Object.assign(backend,{
 async saveAbout(content){if(!backend.user()||!await backend.isAdmin())throw new Error('Administrator access is required.');const rows=await request('/rest/v1/lexamah_about?id=eq.main',{method:'PATCH',body:{content,updated_at:new Date().toISOString()}});if(!rows?.[0])throw new Error('Run supabase/about.sql to set up this page.');return rows[0];},
 async uploadPortrait(file){if(!backend.user()||!await backend.isAdmin())throw new Error('Administrator access is required.');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||!file.size||file.size>5*1024*1024)throw new Error('Choose a JPG, PNG or WebP picture up to 5 MB.');const path=`${backend.user().id}/${crypto.randomUUID()}-${file.name.replace(/[^a-z0-9._-]/gi,'-')}`;const response=await fetch(`${config.url}/storage/v1/object/lexamah-portraits/${encodePath(path)}`,{method:'POST',headers:{apikey:config.key,Authorization:`Bearer ${session.access_token}`,'Content-Type':file.type,'x-upsert':'false'},body:file});const data=await response.json().catch(()=>null);if(!response.ok)throw new Error(data?.message||'Picture upload failed.');return `${config.url}/storage/v1/object/public/lexamah-portraits/${encodePath(path)}`;}
});

Object.assign(backend,{
 recoveryReady(){try{return Boolean(session?.user&&sessionStorage.getItem('lexamah:recovery')==='ready');}catch{return false;}},
 async requestRecovery(email,redirect){const url=new URL(redirect);if(url.origin!==location.origin)throw new Error('Invalid recovery destination.');return request(`/auth/v1/recover?redirect_to=${encodeURIComponent(url.href)}`,{method:'POST',body:{email},auth:false});},
 async acceptRecovery(access,refresh,seconds){const response=await fetch(`${config.url}/auth/v1/user`,{headers:{apikey:config.key,Authorization:`Bearer ${access}`}});if(!response.ok)throw new Error('This recovery link has expired or is invalid. Request a new one.');const user=await response.json();if(!user.id)throw new Error('Invalid recovery session.');session={access_token:access,refresh_token:refresh,expires_at:Math.floor(Date.now()/1000)+Math.max(1,Math.min(seconds,86400)),user};sessionStorage.setItem('lexamah:auth',JSON.stringify(session));sessionStorage.setItem('lexamah:recovery','ready');},
 async resetPassword(password){if(!this.recoveryReady())throw new Error('Open a valid recovery link first.');if(password.length<8||password.length>200)throw new Error('Use a password of 8–200 characters.');await request('/auth/v1/user',{method:'PUT',body:{password}});sessionStorage.removeItem('lexamah:recovery');try{await this.signOut();}finally{session=null;sessionStorage.removeItem('lexamah:auth');}},
 async trackVisit(visitor){return request('/rest/v1/rpc/lexamah_record_visit',{method:'POST',body:{p_visitor_id:visitor}});},
 async adminStats(){if(!backend.user()||!await backend.isAdmin())throw new Error('Administrator access is required.');return request('/rest/v1/rpc/lexamah_admin_stats',{method:'POST',body:{}});}
});

Object.assign(backend,{
 async adminUsers(offset=0,query=''){return request('/rest/v1/rpc/lexamah_admin_users',{method:'POST',body:{p_offset:offset,p_query:query}});},
 async adminAccount(action,user_id,confirm=''){return request('/functions/v1/admin-users',{method:'POST',body:{action,user_id,confirm}});},
 async adminMail(body){return request('/functions/v1/admin-mail',{method:'POST',body});}
});

Object.assign(backend,{
 async resolveAccess(){administrator=false;if(!this.user()||this.recoveryReady())return false;const id=this.user().id;const active=await request('/rest/v1/rpc/lexamah_account_active',{method:'POST',body:{}});if(this.user()?.id!==id)return false;if(active!==true){this.clearSession();throw new Error('Your account is disabled or unavailable.');}const member=await request('/rest/v1/rpc/lexamah_admin_member',{method:'POST',body:{}});if(member===true){const slot=await request('/rest/v1/rpc/lexamah_claim_admin_session',{method:'POST',body:{}});if(this.user()?.id===id)administrator=slot===true;}return administrator;},
 async loadProfile(){if(!this.user())return;const id=this.user().id;const rows=await request(`/rest/v1/lexamah_profiles?user_id=eq.${encodeURIComponent(id)}&select=*`);if(this.user()?.id===id&&rows?.[0]){session.profile=rows[0];sessionStorage.setItem('lexamah:auth',JSON.stringify(session));}},
 async getProgress(){if(!this.user())throw new Error('Log in first.');const rows=await request(`/rest/v1/lexamah_user_progress?user_id=eq.${encodeURIComponent(this.user().id)}&select=data`);return rows?.[0]?.data||null;},
 async saveProgress(id,data){if(this.user()?.id!==id)throw new Error('Account changed.');return request('/rest/v1/lexamah_user_progress?on_conflict=user_id',{method:'POST',body:{user_id:id,data,updated_at:new Date().toISOString()},prefer:'resolution=merge-duplicates,return=representation'});},
 async viewDocument(type,id){if(!this.user())throw new Error('Log in to read documents.');return request('/functions/v1/content-view',{method:'POST',body:{type,id}});}
});
